import{_ as a,c as t,o as r,j as i,Y as n,t as s}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"ip-fou | x-cmd man (ip man8) | Foo-over-UDP receive port configuration","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-fou - Foo-over-UDP receive port configuration","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-fou | x-cmd man (ip man8) | Foo-over-UDP receive port configuration"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-fou - Foo-over-UDP receive port configuration"}]]},"headers":[],"params":{"isMan":true,"man":"ip-fou","category":"ip man8","desc":"Foo-over-UDP receive port configuration"},"relativePath":"ip/man8/ip-fou.md","filePath":"ip/man8/[man].md"}'),p={name:"ip/man8/ip-fou.md"},c={class:"visually-hidden"};function d(o,e,l,u,h,g){return r(),t("div",null,[i("h1",c,s(o.$params.man),1),e[0]||(e[0]=n('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-fou - Foo-over-UDP receive port configuration</p><p>ip-gue - Generic UDP Encapsulation receive port configuration</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip</strong> [ <em>OPTIONS</em> ] <strong>fou</strong> { <em>COMMAND</em> | <strong>help</strong> }</p><p><strong>ip fou add</strong> <strong>port</strong> <em>PORT</em> { <strong>gue</strong> | <strong>ipproto</strong> <em>PROTO</em> } [ <strong>local</strong> <em>IFADDR</em> ] [ <strong>peer</strong> <em>IFADDR</em> ] [ <strong>peer_port</strong> <em>PORT</em> ] [ <strong>dev</strong> <em>IFNAME</em> ] <br><strong>ip fou del</strong> <strong>port</strong> <em>PORT</em> [ <strong>local</strong> <em>IFADDR</em> ] [ <strong>peer</strong><em>IFADDR</em> ] [ <strong>peer_port</strong> <em>PORT</em> ] [ <strong>dev</strong> <em>IFNAME</em> ] <br><strong>ip fou show</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>ip fou</strong> commands are used to create and delete receive ports for Foo-over-UDP (FOU) as well as Generic UDP Encapsulation (GUE).</p><p>Foo-over-UDP allows encapsulating packets of an IP protocol directly over UDP. The receiver infers the protocol of a packet received on a FOU UDP port to be the protocol configured for the port.</p><p>Generic UDP Encapsulation (GUE) encapsulates packets of an IP protocol within UDP and an encapsulation header. The encapsulation header contains the IP protocol number for the encapsulated packet.</p><p>When creating a FOU or GUE receive port, the port number is specified in <em>PORT</em> argument. If FOU is used, the IP protocol number associated with the port is specified in <em>PROTO</em> argument. You can bind a port to a local address/interface, by specifying the address in the local <em>IFADDR</em> argument or the device in the <em>IFNAME</em> argument. If you would like to connect the port, you can specify the peer address in the peer <em>IFADDR</em> argument and peer port in the peer_port <em>PORT</em> argument.</p><p>A FOU or GUE receive port is deleted by specifying <em>PORT</em> in the delete command, as well as local address/interface or peer address/port (if set).</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h3 id="configure-a-fou-receive-port-for-gre-bound-to-7777" tabindex="-1">Configure a FOU receive port for GRE bound to 7777 <a class="header-anchor" href="#configure-a-fou-receive-port-for-gre-bound-to-7777" aria-label="Permalink to &quot;Configure a FOU receive port for GRE bound to 7777&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip fou add port 7777 ipproto 47</span></span></code></pre></div><h3 id="configure-a-fou-receive-port-for-ipip-bound-to-8888" tabindex="-1">Configure a FOU receive port for IPIP bound to 8888 <a class="header-anchor" href="#configure-a-fou-receive-port-for-ipip-bound-to-8888" aria-label="Permalink to &quot;Configure a FOU receive port for IPIP bound to 8888&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip fou add port 8888 ipproto 4</span></span></code></pre></div><h3 id="configure-a-gue-receive-port-bound-to-9999" tabindex="-1">Configure a GUE receive port bound to 9999 <a class="header-anchor" href="#configure-a-gue-receive-port-bound-to-9999" aria-label="Permalink to &quot;Configure a GUE receive port bound to 9999&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip fou add port 9999 gue</span></span></code></pre></div><h3 id="delete-the-gue-receive-port-bound-to-9999" tabindex="-1">Delete the GUE receive port bound to 9999 <a class="header-anchor" href="#delete-the-gue-receive-port-bound-to-9999" aria-label="Permalink to &quot;Delete the GUE receive port bound to 9999&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip fou del port 9999</span></span></code></pre></div><h3 id="configure-a-fou-receive-port-for-gre-bound-to-1-2-3-4-7777" tabindex="-1">Configure a FOU receive port for GRE bound to 1.2.3.4:7777 <a class="header-anchor" href="#configure-a-fou-receive-port-for-gre-bound-to-1-2-3-4-7777" aria-label="Permalink to &quot;Configure a FOU receive port for GRE bound to 1.2.3.4:7777&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip fou add port 7777 ipproto 47 local 1.2.3.4</span></span></code></pre></div><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Tom Herbert &lt;therbert@google.com&gt;</p>',27))])}const b=a(p,[["render",d]]);export{f as __pageData,b as default};
